package in.amanahpay;
import jakarta.servlet.http.HttpServletRequest;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api") public class DashboardController {
 private final JdbcTemplate db; public DashboardController(JdbcTemplate db){this.db=db;}
 @GetMapping("/health") public Map<String,Object> health(){Integer n=db.queryForObject("SELECT 1",Integer.class);return Map.of("status",n==1?"UP":"DOWN","database","mysql");}
 @GetMapping("/dashboard") public Map<String,Object> dashboard(HttpServletRequest r){long merchant=merchant(r);return Map.of("collectedPaise",sum("SELECT COALESCE(SUM(p.amount_paise),0) FROM payments p JOIN plans x ON x.id=p.plan_id WHERE x.merchant_id=? AND p.status='PAID'",merchant),"pendingPaise",sum("SELECT COALESCE(SUM(i.amount_paise),0) FROM installments i WHERE i.merchant_id=? AND i.status IN ('DUE','UPCOMING')",merchant),"overduePaise",sum("SELECT COALESCE(SUM(i.amount_paise),0) FROM installments i WHERE i.merchant_id=? AND i.status='OVERDUE'",merchant),"upcomingPaise",sum("SELECT COALESCE(SUM(i.amount_paise),0) FROM installments i WHERE i.merchant_id=? AND i.status IN ('DUE','UPCOMING') AND i.due_date<=DATE_ADD(CURDATE(),INTERVAL 30 DAY)",merchant),"dueToday",List.of());}
 @GetMapping("/customers") public List<Map<String,Object>> customers(HttpServletRequest r){return db.queryForList("SELECT CAST(c.id AS CHAR) id,c.full_name name,COALESCE(c.phone,'') phone,COUNT(DISTINCT p.id) activePlans,0 paidPaise,0 pendingPaise,DATE_FORMAT(MIN(i.due_date),'%Y-%m-%d') nextDue,'On track' status FROM customers c LEFT JOIN plans p ON p.customer_id=c.id AND p.status='ACTIVE' LEFT JOIN installments i ON i.plan_id=p.id AND i.status IN ('DUE','UPCOMING') WHERE c.merchant_id=? GROUP BY c.id,c.full_name,c.phone ORDER BY c.id DESC",merchant(r));}
 @GetMapping("/plans") public List<Map<String,Object>> plans(HttpServletRequest r){return db.queryForList("SELECT CAST(p.id AS CHAR) id,c.full_name customer,'Purchase plan' item,p.total_amount_paise totalPaise,p.total_amount_paise monthlyPaise,p.total_amount_paise remainingPaise,p.status status,DATE_FORMAT(MIN(i.due_date),'%Y-%m-%d') nextDue FROM plans p JOIN customers c ON c.id=p.customer_id LEFT JOIN installments i ON i.plan_id=p.id AND i.status IN ('DUE','UPCOMING') WHERE p.merchant_id=? GROUP BY p.id,c.full_name,p.total_amount_paise,p.status ORDER BY p.id DESC",merchant(r));}
 private long sum(String sql,long id){Long n=db.queryForObject(sql,Long.class,id);return n==null?0:n;}private long merchant(HttpServletRequest r){Object id=r.getAttribute("amanah.userId");if(id==null)return -1;Long m=db.queryForObject("SELECT merchant_id FROM users WHERE id=?",Long.class,Long.valueOf(id.toString()));return m==null?-1:m;}
}
